import React, { useState } from 'react';
import './App.css';

export interface BookedRange {
  /** The first booked night, as an ISO date. */
  from: string;
  /** The check-out day after the last booked night, so a range is half-open. */
  to: string;
}

export interface Listing {
  name: string;
  currency: string;
  nightlyPrice: number;
  cleaningFee: number;
  includedGuests: number;
  extraGuestFee: number;
  maxGuests: number;
  booked: BookedRange[];
}

/** One listing; every price is in whole units of its currency. */
export const LISTING: Listing = {
  name: 'Lakeside cabin',
  currency: 'USD',
  nightlyPrice: 180,
  cleaningFee: 60,
  includedGuests: 2,
  extraGuestFee: 25,
  maxGuests: 4,
  booked: [{ from: '2026-12-24', to: '2026-12-27' }],
};

/** Exchange rates from the listing currency, for the currency follow-up. */
export const RATES: Record<string, number> = { USD: 1, EUR: 0.92 };

// TODO: count the nights between the two dates and price the stay: the nightly price covers
// LISTING.includedGuests, each guest after that adds LISTING.extraGuestFee a night, and the cleaning fee is added once.
// TODO: show an error when check-out is on or before check-in, and "Those dates are booked" when the stay
// overlaps a range in LISTING.booked; in both cases there is no total and Book now is disabled.
// TODO: Book now opens a confirmation dialog that takes focus, closes on Escape or Cancel, and returns focus.

export default function App() {
  const [checkIn, setCheckIn] = useState('');
  const [checkOut, setCheckOut] = useState('');
  const [adults, setAdults] = useState(1);
  const [children, setChildren] = useState(0);

  return (
    <main className="main">
      <section className="card" aria-labelledby="listing-title">
        <header className="header">
          <h1 id="listing-title" className="title">{LISTING.name}</h1>
          <p className="subtitle">
            ${LISTING.nightlyPrice} a night for {LISTING.includedGuests} guests · up to {LISTING.maxGuests} guests
          </p>
        </header>

        <div className="dates">
          <label className="field">
            <span className="label">Check-in</span>
            <input className="check-in" type="date" value={checkIn} onChange={(event) => setCheckIn(event.target.value)} />
          </label>
          <label className="field">
            <span className="label">Check-out</span>
            <input className="check-out" type="date" value={checkOut} onChange={(event) => setCheckOut(event.target.value)} />
          </label>
        </div>

        <fieldset className="guests">
          <legend className="label">Guests</legend>
          <div className="counter adults">
            <span className="counter-name">Adults</span>
            <button type="button" className="step adults-minus" aria-label="Remove one from adults" onClick={() => setAdults(adults - 1)}>
              -
            </button>
            <output className="adults-count">{adults}</output>
            <button type="button" className="step adults-plus" aria-label="Add one to adults" onClick={() => setAdults(adults + 1)}>
              +
            </button>
          </div>
          <div className="counter children">
            <span className="counter-name">Children</span>
            <button type="button" className="step children-minus" aria-label="Remove one from children" onClick={() => setChildren(children - 1)}>
              -
            </button>
            <output className="children-count">{children}</output>
            <button type="button" className="step children-plus" aria-label="Add one to children" onClick={() => setChildren(children + 1)}>
              +
            </button>
          </div>
        </fieldset>

        <p className="hint">Pick your dates to see the price.</p>

        <button type="button" className="book">
          Book now
        </button>
      </section>
    </main>
  );
}

